var fax_disabled,fax_prev_disabled;function fax_pre_select_cb(path,idx,first){if(first)return;idx=+idx;var menu_n=parseInt(path.split('fax.menu')[1]);w3_select_enum(path,function(option){if(option.disabled){fax_prev_disabled=fax_disabled;fax_disabled=option;}
if(option.value==idx&&!option.disabled){var inner=option.innerHTML;console.log('fax_pre_select_cb opt.val='+option.value+' opt.inner='+inner);var lsb=inner.includes('lsb');var freq=parseFloat(inner);ext_tune(freq+(lsb?1.9:-1.9),lsb?'lsb':'usb',ext_zoom.ABS,11);var lo=lsb?-fax.pbH:fax.pbL;var hi=lsb?-fax.pbL:fax.pbH;ext_set_passband(lo,hi);fax.freq=ext_get_freq()/1e3;w3_el('id-fax-station').innerHTML='<b>Station: '+fax_prev_disabled.innerHTML+', '+fax_disabled.innerHTML+'</b>';var s=inner.split('/');var lpm=120,t;if(s.length>1&&!isNaN(t=parseInt(s[1])))lpm=t;fax_lpm(lpm);w3_select_set_if_includes('fax.lpm_i','\\b'+lpm+'\\b');w3_select_value(path,idx);}});fax_clear_menus(menu_n);}
function fax_clear_menus(except){for(var i=0;i<fax.n_menu;i++){if(isNoArg(except)||i!=except)
w3_select_value('fax.menu'+i,-1);}}
function FAX_environment_changed(changed){if(changed.freq||changed.mode){var dsp_freq=ext_get_freq()/1e3;var mode=ext_get_mode();var m=mode.substr(0,2);if(fax.freq!=dsp_freq||(m!='us'&&m!='ls')){fax_clear_menus();w3_el('id-fax-station').innerHTML='&nbsp;';}}
if(changed.resize){var el=w3_el('id-fax-data');if(!el)return;var width=fax.tw+kiwi.time_display_width;ext_set_data_width(width);var left=Math.max(0,(window.innerWidth-width)/ 2);console.log('FAX resize left='+left);el.style.left=px(left);fax.startx=Math.round(left);}}
function fax_mousedown(evt){fax_shift(evt,true);}
function fax_touchstart(evt){fax_shift(evt,false);}
function fax_shift(evt,requireShiftKey){var xy=w3_canvas_event_xy(evt,fax.data_canvas);var offset=xy.x;if(!requireShiftKey)alert('off='+offset+' fax.tw='+fax.tw);if((requireShiftKey&&!evt.shiftKey)||offset<0||offset>=fax.w)return;var norm=(offset / fax.w).toFixed(6);console.log('FAX offset='+offset+' shift='+norm);var data_canvas=fax.data_canvas;var copy_canvas=fax.copy_canvas;var dct=data_canvas.ctx;var cct=copy_canvas.ctx;var w=fax.w;var h=fax.h;var w0=offset;var w1=w-w0;cct.drawImage(data_canvas,w0,0,w1,h,0,0,w1,h);dct.drawImage(data_canvas,0,0,w0,h,w1,0,w0,h);dct.drawImage(copy_canvas,0,0,w1,h,0,0,w1,h);ext_send('SET fax_shift='+norm);}
function fax_start_stop(start){if(start)
ext_send('SET fax_start lpm='+fax.lpm+' phasing='+(fax.phasing?1:0)+' autostop='+(fax.autostop?1:0)+' debug='+(fax.debug?1:0));else
ext_send('SET fax_stop');}
function fax_stop_start_cb(path,idx,first){fax_start_stop(fax.stop_start_state);fax.stop_start_state^=1;w3_button_text(path,fax.stop_start_state?'Start':'Stop');w3_visible('id-fax-stopped',false);}
function fax_phasing_cb(path,checked,first){if(first)return;fax.phasing=checked;if(!fax.stop_start_state){fax_start_stop(0);fax_start_stop(1);}}
function fax_autostop_cb(path,checked,first){if(first)return;fax.autostop=checked;if(!fax.stop_start_state){fax_start_stop(0);fax_start_stop(1);}}
function fax_lpm(lpm){console.log('fax_lpm lpm='+lpm+' fax.lpm='+fax.lpm);if(isNaN(lpm))return;if(fax.lpm==lpm)return;fax.lpm=lpm;if(!fax.stop_start_state){fax_start_stop(0);fax_start_stop(1);}}
function fax_lpm_cb(path,idx,first){if(first)return;idx=+idx;lpm=fax.lpm_s[idx];fax_lpm(lpm);}
function fax_clear_cb(){fax_clear_display();}
function fax_save_cb(path,val,first){if(first)return;var imgURL=fax.data_canvas.toDataURL("image/jpeg",0.85);var dlLink=document.createElement('a');dlLink.download=kiwi_timestamp_filename('FAX.','.jpg');dlLink.href=imgURL;dlLink.target='_blank';dlLink.dataset.downloadurl=["image/jpeg",dlLink.download,dlLink.href].join(':');document.body.appendChild(dlLink);dlLink.click();document.body.removeChild(dlLink);}
function FAX_blur(){ext_send('SET fax_stop');ext_set_data_height();ext_restore_setup(fax.saved_setup);}
function FAX_config_html(){ext_config_html(fax,'fax','FAX','FAX configuration');}
function FAX_help(show){if(show){var s='From <b><a href="https://github.com/seandepagnier/weatherfax_pi" target="_blank">weatherfax_pi</a></b> by Sean D\'Epagnier &copy;2015<br><br>'+'When "auto align" is checked the phasing information sent at the beginning of most '+'FAXes is used to horizontally align the image. This may not work if the signal is not strong.<br><br>'+'When "auto stop" is checked the start and stop tones sent at the beginning and end of most '+'FAXes is used to stop the window scrolling. This may not work if the signal is not strong.<br><br>'+'Most stations use an LPM (lines per minute) value of 120. The exception is JJC/JSC which '+'mostly uses 60. <br><br>'+'You can manually align the image by shift-clicking (touch on mobile devices) at the location '+'you want moved to the left edge. <br><br>'+'URL parameters: <br>'+'First parameter can be a frequency matching an entry in the station menus. '+
w3_text('|color:orange','align<i>[:0|1]</i> &nbsp; stop<i>[:0|1]</i> &nbsp; lpm:<i>value</i>')+'<br> So for example this is valid: <i>ext=fax,3855,align,stop</i>';confirmation_show_scrolling_content('FAX decoder help',s,620,375);}
return true;}



